    private static Product Create(
        string name,
        string description,
        decimal price,
        int stock,
        int totalSold,
        Category category,
        string? imageUrl)
    {
        return new Product
        {
            Name = name,
            Description = description,
            Price = price,
            Stock = stock,
            ReservedStock = 0,
            TotalSold = totalSold,
            Category = category,
            ImageUrl = imageUrl
        };
    }
}
